#!/usr/bin/env node

/**
 * Set Subscription Prices Script
 * 
 * Sets prices for subscriptions in App Store Connect using data from a JSON file
 * generated by generate-product-ids.js. Sets prices for all territories based on
 * the USD price specified in the JSON file.
 * 
 * Usage:
 *   node set-subscription-prices.js <json-file-path> [--dry-run]
 *   npm run set-prices -- product-ids-test3.json
 *   npm run set-prices -- product-ids-test3.json --dry-run
 */

const fs = require('fs');
const appService = require('./src/services/apps');
const subscriptionService = require('./src/services/subscriptions');
const logger = require('./src/utils/logger');

const BUNDLE_ID = 'com.vtech.plus.inapp.ios.test3';

/**
 * Display help message
 */
function showHelp() {
  console.log(`
Set Subscription Prices from JSON

Usage:
  node set-subscription-prices.js <json-file-path> [options]
  npm run set-prices -- <json-file-path> [options]

Arguments:
  json-file-path    Path to the JSON file (output from generate-product-ids.js)

Options:
  --dry-run         Preview what would be set without making changes
  --help, -h        Show this help message

Examples:
  node set-subscription-prices.js product-ids-test3.json
  node set-subscription-prices.js product-ids-test3.json --dry-run
  npm run set-prices -- product-ids-test3.json

Process:
  1. Reads the JSON file with subscription data (including USD prices)
  2. Fetches subscription IDs from App Store Connect
  3. For each subscription, finds the price point matching the USD price
  4. Sets the price for all territories using the same price tier
  5. Reports success/failure for each operation

Note:
  - Prices are set using Apple's price tier system
  - The USD price determines the tier, which maps to equivalent prices in all territories
  - Price changes take effect immediately
`);
}

/**
 * Main function
 */
async function main() {
  const args = process.argv.slice(2);
  
  // Check for help flag
  if (args.includes('--help') || args.includes('-h')) {
    showHelp();
    process.exit(0);
  }
  
  // Check for dry-run flag
  const dryRun = args.includes('--dry-run');
  const jsonPath = args.find(arg => !arg.startsWith('--'));
  
  if (!jsonPath) {
    console.error('Error: JSON file path is required\n');
    showHelp();
    process.exit(1);
  }
  
  if (!fs.existsSync(jsonPath)) {
    console.error(`Error: File not found: ${jsonPath}`);
    process.exit(1);
  }
  
  console.log('='.repeat(70));
  console.log('Set Subscription Prices');
  console.log('='.repeat(70));
  
  if (dryRun) {
    console.log('\n[DRY-RUN MODE] No changes will be made\n');
  }
  
  try {
    // Read JSON file
    const data = JSON.parse(fs.readFileSync(jsonPath, 'utf-8'));
    console.log(`\nSource file: ${jsonPath}`);
    console.log(`Bundle ID: ${data.bundleId || BUNDLE_ID}`);
    
    // Get app information and existing subscriptions
    console.log('\nFetching subscription data from App Store Connect...');
    const existingData = await appService.getSubscriptionProductIdsByBundleId(
      data.bundleId || BUNDLE_ID,
      { useCache: false }
    );
    
    console.log(`\nApp ID: ${existingData.appId}`);
    console.log(`Total Subscriptions: ${existingData.subscriptions.length}`);
    
    // Build a map of productId -> subscription data (including ID)
    const subscriptionMap = new Map();
    existingData.subscriptions.forEach(sub => {
      subscriptionMap.set(sub.productId, sub);
    });
    
    // Track results
    const results = {
      total: 0,
      success: 0,
      failed: 0,
      skipped: 0,
      noPrice: 0,
      notFound: 0,
      errors: []
    };
    
    // Process each subscription group
    console.log('\n' + '-'.repeat(70));
    console.log('Setting Prices');
    console.log('-'.repeat(70));
    
    for (const group of data.subscriptionGroups) {
      console.log(`\nGroup: ${group.groupName}`);
      
      for (const subscription of group.subscriptions) {
        results.total++;
        const productId = subscription.productId;
        const price = subscription.price;
        
        console.log(`\n  Product: ${productId}`);
        
        // Check if subscription exists
        const existingSub = subscriptionMap.get(productId);
        if (!existingSub) {
          console.log(`    [NOT FOUND] Subscription not found in App Store Connect`);
          results.notFound++;
          continue;
        }
        
        // Check if price is specified
        if (!price) {
          console.log(`    [NO PRICE] No price specified in JSON`);
          results.noPrice++;
          continue;
        }
        
        console.log(`    Subscription ID: ${existingSub.id}`);
        console.log(`    Target USD Price: $${price}`);
        
        if (dryRun) {
          console.log(`    [DRY-RUN] Would set price to $${price} USD for all territories`);
          results.skipped++;
          continue;
        }
        
        try {
          // Set prices for all territories
          console.log(`    Setting prices for all territories...`);
          
          const priceResults = await subscriptionService.setSubscriptionPricesAllTerritories(
            existingSub.id,
            price,
            {
              dryRun: false,
              onProgress: (territory, success, error) => {
                if (success) {
                  process.stdout.write('.');
                } else {
                  process.stdout.write('x');
                }
              }
            }
          );
          
          console.log(''); // New line after progress dots
          console.log(`    [SUCCESS] Set prices: ${priceResults.success}/${priceResults.total} territories`);
          
          if (priceResults.failed > 0) {
            console.log(`    [PARTIAL] ${priceResults.failed} territories failed`);
            priceResults.errors.slice(0, 3).forEach(err => {
              console.log(`      - ${err.territory}: ${err.error}`);
            });
          }
          
          results.success++;
          
        } catch (error) {
          console.log(`    [ERROR] ${error.message}`);
          results.failed++;
          results.errors.push({ productId, error: error.message });
        }
        
        // Add a delay between subscriptions to avoid rate limiting
        await new Promise(resolve => setTimeout(resolve, 1000));
      }
    }
    
    // Print summary
    console.log('\n' + '='.repeat(70));
    console.log('Summary');
    console.log('='.repeat(70));
    console.log(`\nSubscriptions Processed: ${results.total}`);
    console.log(`  Prices Set Successfully: ${results.success}`);
    console.log(`  Failed: ${results.failed}`);
    console.log(`  Not Found: ${results.notFound}`);
    console.log(`  No Price Specified: ${results.noPrice}`);
    
    if (dryRun) {
      console.log(`  Skipped (Dry Run): ${results.skipped}`);
      console.log('\n[DRY-RUN] No changes were made. Remove --dry-run to execute.');
    }
    
    if (results.errors.length > 0) {
      console.log('\nErrors:');
      results.errors.forEach(err => {
        console.log(`  - ${err.productId}: ${err.error}`);
      });
    }
    
    // Exit with error code if any failures
    if (results.failed > 0) {
      process.exit(1);
    }
    
  } catch (error) {
    console.error(`\nFatal error: ${error.message}`);
    logger.error('Set subscription prices failed:', error);
    process.exit(1);
  }
}

main();
